import{_ as n,o as a,c as l,a0 as p}from"./chunks/framework.DqMqoJl9.js";const e="data:image/png;base64,",o="data:image/png;base64,",c="data:image/png;base64,",r="data:image/png;base64,",E=JSON.parse('{"title":"HD 钱包","description":"","frontmatter":{},"headers":[],"relativePath":"blockChain/8-hd.md","filePath":"blockChain/8-hd.md","lastUpdated":1791573371000}'),t={name:"blockChain/8-hd.md"};function i(y,s,b,d,u,m){return a(),l("div",null,[...s[0]||(s[0]=[p('<h1 id="hd-钱包" tabindex="-1">HD 钱包 <a class="header-anchor" href="#hd-钱包" aria-label="Permalink to &quot;HD 钱包&quot;">​</a></h1><h2 id="_1-原理" tabindex="-1">1 原理 <a class="header-anchor" href="#_1-原理" aria-label="Permalink to &quot;1 原理&quot;">​</a></h2><h3 id="_1-1-什么是-hd-钱包" tabindex="-1">1.1 什么是 HD 钱包 <a class="header-anchor" href="#_1-1-什么是-hd-钱包" aria-label="Permalink to &quot;1.1 什么是 HD 钱包&quot;">​</a></h3><p><strong>钱包的特性：</strong></p><ul><li>任何人都可以自己独立的，不联网的生成自己的钱包</li><li>钱不在钱包里。钱包唯一记录就是一个私钥</li><li>钱的数量存在区块链上</li></ul><p>通常不同币种的钱包生成的私钥是不同的</p><p><strong>HD 钱包：</strong></p><p>能不能只用一个私钥管理成千上万个地址？实际上是可以的。虽然椭圆曲线算法决定了一个私钥只能对应一个公钥，但是，可以通过某种确定性算法，先确定一个私钥 k1，然后计算出 <code>k2、k3、k4……</code> 等其他私钥，就相当于只需要管理一个私钥，剩下的私钥可以按需计算出来</p><blockquote><p>这种根据某种确定性算法，只需要管理一个根私钥，即可实时计算所有 “子私钥” 的管理方式，称为 HD 钱包。HD 是 <code>Hierarchical Deterministic</code> 的缩写，意思是分层确定性</p></blockquote><p>先确定根私钥 root，然后根据索引计算每一层的子私钥：</p><p><img src="'+e+'" alt=""></p><p>HD 层级实际上是无限的，每一层索引从 0 ～ 232，约 43 亿个子 key。这种计算被称为衍生（Derivation）</p><h3 id="_1-2-如何计算子私钥" tabindex="-1">1.2 如何计算子私钥 <a class="header-anchor" href="#_1-2-如何计算子私钥" aria-label="Permalink to &quot;1.2 如何计算子私钥&quot;">​</a></h3><p>如何根据某个私钥计算下一层的子私钥？</p><p>HD 钱包采用的计算子私钥的算法是一个扩展的 512 位私钥，记作 xprv，它通过 SHA-512 算法配合 ECC 计算出子扩展私钥，仍然是 512 位。<strong>通过扩展私钥可计算出用于签名的私钥以及公钥</strong></p><p>简单来说，只要给定一个根扩展私钥（随机 512 位整数），即可计算其任意索引的子扩展私钥。扩展私钥总是能计算出扩展公钥，记作 xpub：</p><p><img src="'+o+'" alt=""></p><p>从 xprv 及其对应的 xpub 可计算出真正用于签名的私钥和公钥。之所以要设计这种算法，是因为扩展公钥 xpub 也有一个特点，那就是可以直接计算其子层级的扩展公钥：</p><p><img src="'+c+'" alt=""></p><blockquote><p>因为 xpub 只包含公钥，不包含私钥，因此，可以安全地把 xpub 交给第三方（例如，一个观察钱包），它可以根据 xpub 计算子层级的所有地址，然后在比特币的链上监控这些地址的余额</p></blockquote><p><strong>因此，HD 钱包通过分层确定性算法，实现了以下功能：</strong></p><ul><li>只要确定了扩展私钥 xprv，即可根据索引计算下一层的任何扩展私钥</li><li>只要确定了扩展公钥 xpub，即可根据索引计算下一层的任何扩展公钥</li><li>用户只需保存顶层的一个扩展私钥，即可计算出任意一层的任意索引的扩展私钥</li></ul><blockquote><p>比特币的 BIP-32 规范详细定义了 HD 算法原理和各种推导规则，可阅读此文档以便实现 HD 钱包</p></blockquote><h2 id="_2-钱包层级" tabindex="-1">2 钱包层级 <a class="header-anchor" href="#_2-钱包层级" aria-label="Permalink to &quot;2 钱包层级&quot;">​</a></h2><p>通常把根扩展私钥记作 <code>m</code>，子扩展私钥按层级记作 <code>m/x/y/z</code> 等</p><p><img src="'+r+`" alt=""></p><p>例如，<code>m/0/2</code> 表示从 <code>m</code> 扩展到 <code>m/0</code>（索引为 0）再扩展到 <code>m/0/2</code>（索引为 2）</p><h3 id="_2-1-实例-计算-hd-地址" tabindex="-1">2.1 实例：计算 HD 地址 <a class="header-anchor" href="#_2-1-实例-计算-hd-地址" aria-label="Permalink to &quot;2.1 实例：计算 HD 地址&quot;">​</a></h3><p><strong>通过 <code>bitcoinjs-lib</code> 来计算 HD 地址：</strong></p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bitcoin</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bitcoinjs-lib&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 以 xprv 开头的 xprv9s21ZrQH...是 512 位扩展私钥的 Base58 编码，解码后得到的就是原始扩展私钥</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> xprv </span><span style="color:#D73A49;">=</span></span>
<span class="line"><span style="color:#032F62;">  &#39;xprv9s21ZrQH143K4EKMS3q1vbJo564QAbs98BfXQME6nk8UCrnXnv8vWg9qmtup3kTug96p5E3AvarBhPMScQDqMhEEm41rpYEdXBL8qzVZtwz&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> root </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bitcoin.HDNode.</span><span style="color:#6F42C1;">fromBase58</span><span style="color:#24292E;">(xprv);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// m/0:</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> m_0 </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> root.</span><span style="color:#6F42C1;">derive</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xprv m/0: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_0.</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xpub m/0: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_0.</span><span style="color:#6F42C1;">neutered</span><span style="color:#24292E;">().</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39; prv m/0: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_0.keyPair.</span><span style="color:#6F42C1;">toWIF</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39; pub m/0: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_0.keyPair.</span><span style="color:#6F42C1;">getAddress</span><span style="color:#24292E;">());</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// m/1:</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> m_1 </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> root.</span><span style="color:#6F42C1;">derive</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xprv m/1: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_1.</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xpub m/1: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_1.</span><span style="color:#6F42C1;">neutered</span><span style="color:#24292E;">().</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39; prv m/1: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_1.keyPair.</span><span style="color:#6F42C1;">toWIF</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39; pub m/1: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> m_1.keyPair.</span><span style="color:#6F42C1;">getAddress</span><span style="color:#24292E;">());</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p><strong>某个 xpub 在没有 xprv 的前提下推算子公钥：</strong></p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bitcoin</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bitcoinjs-lib&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> xprv </span><span style="color:#D73A49;">=</span></span>
<span class="line"><span style="color:#032F62;">  &#39;xprv9s21ZrQH143K4EKMS3q1vbJo564QAbs98BfXQME6nk8UCrnXnv8vWg9qmtup3kTug96p5E3AvarBhPMScQDqMhEEm41rpYEdXBL8qzVZtwz&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> root </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bitcoin.HDNode.</span><span style="color:#6F42C1;">fromBase58</span><span style="color:#24292E;">(xprv);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// m/0:</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> m_0 </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> root.</span><span style="color:#6F42C1;">derive</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> xprv_m_0 </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> m_0.</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> xpub_m_0 </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> m_0.</span><span style="color:#6F42C1;">neutered</span><span style="color:#24292E;">().</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 方法一：从 m/0 的扩展私钥推算 m/0/99 的公钥地址:</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> pub_99a </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bitcoin.HDNode.</span><span style="color:#6F42C1;">fromBase58</span><span style="color:#24292E;">(xprv_m_0)</span></span>
<span class="line"><span style="color:#24292E;">  .</span><span style="color:#6F42C1;">derive</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">99</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#24292E;">  .</span><span style="color:#6F42C1;">getAddress</span><span style="color:#24292E;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 方法二：从 m/0 的扩展公钥推算 m/0/99 的公钥地址:</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> pub_99b </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bitcoin.HDNode.</span><span style="color:#6F42C1;">fromBase58</span><span style="color:#24292E;">(xpub_m_0)</span></span>
<span class="line"><span style="color:#24292E;">  .</span><span style="color:#6F42C1;">derive</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">99</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#24292E;">  .</span><span style="color:#6F42C1;">getAddress</span><span style="color:#24292E;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 比较公钥地址是否相同:</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(pub_99a);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(pub_99b);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><h3 id="_2-2-bip-44-钱包层级规范" tabindex="-1">2.2 BIP-44 钱包层级规范 <a class="header-anchor" href="#_2-2-bip-44-钱包层级规范" aria-label="Permalink to &quot;2.2 BIP-44 钱包层级规范&quot;">​</a></h3><p>HD 钱包理论上有无限的层级，对使用 <code>secp256k1</code> 算法的任何币都适用。但是，如果一种钱包使用 <code>m/1/2/x</code>，另一种钱包使用 <code>m/3/4/x</code>，没有一种统一的规范，就会乱套</p><p><strong>比特币的 <code>BIP-44</code> 规范定义了一种如何派生私钥的标准：</strong></p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>m / purpose&#39; / coin_type&#39; / account&#39; / change / address_index</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>purpose</code> 总是 44</li><li><code>coin_type</code> 在 <code>SLIP-44</code> 中定义，例如，<code>0 = BTC</code>，<code>2 = LTC</code>，<code>60 = ETH</code> 等</li><li><code>account</code> 表示用户的某个“账户”，由用户自定义索引</li><li><code>change = 0</code> 表示外部交易，<code>change = 1</code> 表示内部交易</li><li><code>address_index</code> 则是真正派生的索引为 <code>0 ～ 2^31</code> 的地址</li></ul><p><strong>例如，某个比特币钱包给用户创建的一组 HD 地址实际上是：</strong></p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>m/44&#39;/0&#39;/0&#39;/0/0</span></span>
<span class="line"><span>m/44&#39;/0&#39;/0&#39;/0/1</span></span>
<span class="line"><span>m/44&#39;/0&#39;/0&#39;/0/2</span></span>
<span class="line"><span>m/44&#39;/0&#39;/0&#39;/0/3</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>如果是莱特币钱包，则用户的 HD 地址是：</strong></p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>m/44&#39;/2&#39;/0&#39;/0/0</span></span>
<span class="line"><span>m/44&#39;/2&#39;/0&#39;/0/1</span></span>
<span class="line"><span>m/44&#39;/2&#39;/0&#39;/0/2</span></span>
<span class="line"><span>m/44&#39;/2&#39;/0&#39;/0/3</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>实现了 <code>BIP-44</code> 规范的钱包可以管理所有币种。相同的根扩展私钥在不同钱包上派生的一组地址都是相同的</p></blockquote><h2 id="_3-助记词" tabindex="-1">3 助记词 <a class="header-anchor" href="#_3-助记词" aria-label="Permalink to &quot;3 助记词&quot;">​</a></h2><h3 id="_3-1-助记词是什么" tabindex="-1">3.1 助记词是什么 <a class="header-anchor" href="#_3-1-助记词是什么" aria-label="Permalink to &quot;3.1 助记词是什么&quot;">​</a></h3><p>从 HD 钱包的创建方式可知，要创建一个 HD 钱包，我们必须首先有一个确定的 <code>512bit</code>（64 字节）的随机数种子</p><p>如果用电脑生成一个 64 字节的随机数作为种子当然是可以的，但是恐怕谁也记不住。</p><p>如果自己想一个句子，例如 <code>bitcoin is awesome</code>，然后计算 <code>SHA-512</code> 获得这个 64 字节的种子，虽然是可行的，但是其安全性取决于自己想的句子到底有多随机。像 <code>bitcoin is awesome</code> 本质上就是 3 个英文单词构成的随机数，长度太短，所以安全性非常差</p><blockquote><p>为了解决初始化种子的易用性问题，<code>BIP-39</code> 规范提出了一种通过助记词来推算种子的算法</p></blockquote><h3 id="_3-2-如何生成助记词" tabindex="-1">3.2 如何生成助记词 <a class="header-anchor" href="#_3-2-如何生成助记词" aria-label="Permalink to &quot;3.2 如何生成助记词&quot;">​</a></h3><ol><li>挑选 2048 个常用的英文单词，构造一个数组：<code>const words = [&#39;abandon&#39;, &#39;ability&#39;, &#39;able&#39;, ..., &#39;zoo&#39;]</code></li><li>生成 <code>128~256</code> 位随机数，注意随机数的总位数必须是 32 的倍数。例如，生成的 256 位随机数以 16 进制表示为：<code>179e5af5ef66e5da5049cd3de0258c5339a722094e0fdbbbe0e96f148ae80924</code></li><li>在随机数末尾加上校验码，校验码取 <code>SHA-256</code> 的前若干位，并使得总位数凑成 11 的倍数</li><li>上述随机数校验码的二进制表示为 <code>00010000</code></li><li>将 <code>随机数 + 校验码</code> 按每 <code>11 bit</code> 一组，得到范围是 <code>0 ~ 2047</code> 的 24 个整数</li><li>把这 24 个整数作为索引，就得到了最多 24 个助记词</li></ol><p>例如：bleak version runway tell hour unfold donkey defy digital abuse glide please omit much cement sea sweet tenant demise taste emerge inject cause link</p><p>由于在生成助记词的过程中引入了校验码，所以，助记词如果弄错了，软件可以提示用户输入的助记词可能不对</p><blockquote><p>生成助记词的过程是计算机随机产生的，用户只要记住这些助记词，就可以根据助记词推算出 HD 钱包的种子。注意：不要自己挑选助记词，原因一是随机性太差，二是缺少校验</p></blockquote><h3 id="_3-3-实例-生成助记词" tabindex="-1">3.3 实例：生成助记词 <a class="header-anchor" href="#_3-3-实例-生成助记词" aria-label="Permalink to &quot;3.3 实例：生成助记词&quot;">​</a></h3><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 生成助记词可以使用 bip39 这个 JavaScript 库</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bip39</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bip39&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> words </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">generateMnemonic</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">256</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(words);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;is valid mnemonic? &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">validateMnemonic</span><span style="color:#24292E;">(words));</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>如果想用中文作助记词也是可以的，给 <code>generateMnemonic()</code> 传入一个中文助记词数组即可：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bip39</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bip39&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 第二个参数 rng 可以为 null:</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> words </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">generateMnemonic</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">256</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">null</span><span style="color:#24292E;">, bip39.wordlists.chinese_simplified);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(words);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><blockquote><p>注意：同样索引的中文和英文生成的 HD 种子是不同的。各种语言的助记词定义在 <code>bip-0039-wordlists.md</code></p></blockquote><h3 id="_3-4-根据助记词推算种子" tabindex="-1">3.4 根据助记词推算种子 <a class="header-anchor" href="#_3-4-根据助记词推算种子" aria-label="Permalink to &quot;3.4 根据助记词推算种子&quot;">​</a></h3><p>根据助记词推算种子的算法是 <code>PBKDF2</code>，使用的哈希函数是 <code>Hmac-SHA512</code>，其中，输入是助记词的 <code>UTF-8</code> 编码，并设置 <code>Key</code> 为 <code>mnemonic + 用户口令</code>，循环 2048 次，得到最终的 64 字节种子</p><p>上述助记词加上口令 bitcoin 得到的 HD 种子是：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>b59a8078d4ac5c05b0c92b775b96a466cd136664bfe14c1d49aff3ccc94d52dfb1d59ee628426192eff5535d6058cb64317ef2992c8b124d0f72af81c9ebfaaa</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>该种子即为 HD 钱包的种子</strong></p><blockquote><p>注意：用户除了需要记住助记词外，还可以额外设置一个口令。HD 种子的生成依赖于助记词和口令，丢失助记词或者丢失口令（如果设置了口令的话）都将导致 HD 钱包丢失！</p></blockquote><h3 id="_3-4-实例-生成种子" tabindex="-1">3.4 实例：生成种子 <a class="header-anchor" href="#_3-4-实例-生成种子" aria-label="Permalink to &quot;3.4 实例：生成种子&quot;">​</a></h3><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bip39</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bip39&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 生成助记词</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> words </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">generateMnemonic</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">256</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 生成种子</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> seedBuffer </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">mnemonicToSeed</span><span style="color:#24292E;">(words);</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> seedAsHex </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> seedBuffer.</span><span style="color:#6F42C1;">toString</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;hex&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// or use bip39.mnemonicToSeedHex(words)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(words);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(seedAsHex);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>根据助记词和口令生成 HD 种子的方法是在 <code>mnemonicToSeed()</code> 函数中传入 <code>password</code>：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bip39</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bip39&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 生成助记词</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> words </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">generateMnemonic</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">256</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(words);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> password </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;bitcoin&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 生成种子</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> seedAsHex </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">mnemonicToSeedHex</span><span style="color:#24292E;">(words, password);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(seedAsHex);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="_3-5-完整实例" tabindex="-1">3.5 完整实例 <a class="header-anchor" href="#_3-5-完整实例" aria-label="Permalink to &quot;3.5 完整实例&quot;">​</a></h3><p>我们使用 <code>助记词 + 口令</code> 的方式来生成一个 HD 钱包的 HD 种子并计算出根扩展私钥：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bitcoin</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bitcoinjs-lib&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bip39</span><span style="color:#D73A49;"> =</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;bip39&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> words</span><span style="color:#D73A49;"> =</span></span>
<span class="line"><span style="color:#032F62;">  &#39;bleak version runway tell hour unfold donkey defy digital abuse glide please omit much cement sea sweet tenant demise taste emerge inject cause link&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> password</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> &#39;bitcoin&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 计算 seed</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> seedHex </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bip39.</span><span style="color:#6F42C1;">mnemonicToSeedHex</span><span style="color:#24292E;">(words, password);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;seed: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> seedHex); </span><span style="color:#6A737D;">// b59a8078...c9ebfaaa</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 生成 root</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> root </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> bitcoin.HDNode.</span><span style="color:#6F42C1;">fromSeedHex</span><span style="color:#24292E;">(seedHex);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xprv: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> root.</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">()); </span><span style="color:#6A737D;">// xprv9s21ZrQH...uLgyr9kF</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xpub: &#39;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> root.</span><span style="color:#6F42C1;">neutered</span><span style="color:#24292E;">().</span><span style="color:#6F42C1;">toBase58</span><span style="color:#24292E;">()); </span><span style="color:#6A737D;">// xpub661MyMwA...oy32fcRG</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 生成派生 key</span></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> child0 </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> root.</span><span style="color:#6F42C1;">derivePath</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;m/44&#39;/0&#39;/0&#39;/0/0&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;prv m/44&#39;/0&#39;/0&#39;/0/0: &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> child0.keyPair.</span><span style="color:#6F42C1;">toWIF</span><span style="color:#24292E;">()); </span><span style="color:#6A737D;">// KzuPk3PXKdnd6QwLqUCK38PrXoqJfJmACzxTaa6TFKzPJR7H7AFg</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;pub m/44&#39;/0&#39;/0&#39;/0/0: &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> child0.</span><span style="color:#6F42C1;">getAddress</span><span style="color:#24292E;">()); </span><span style="color:#6A737D;">// 1PwKkrF366RdTuYsS8KWEbGxfP4bikegcS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>可以通过 <a href="https://iancoleman.io/bip39/" target="_blank" rel="noreferrer">https://iancoleman.io/bip39/</a> 在线测试 <code>BIP-39</code> 并生成 HD 钱包</p><h2 id="_4-地址监控" tabindex="-1">4 地址监控 <a class="header-anchor" href="#_4-地址监控" aria-label="Permalink to &quot;4 地址监控&quot;">​</a></h2><p><strong>地址数量过大问题：</strong></p><p>一个 HD 钱包管理的是一组自动计算的地址。以比特币为例，在确定了根扩展私钥 m 后，得到一组地址为 <code>m/44&#39;/0&#39;/0&#39;/0/x</code>，其中 <code>x = 0 ~ 2^31</code></p><p>HD 钱包需要在链上监控每个 TX 的输入和输出，看看上述管理的一组地址是否存在于输入和输出中。如果作为输入，则钱包余额减少，如果作为输出，则钱包余额增加</p><p>现在问题来了：如何根据 TX 的输入和输出地址快速判断这些地址中是否存在 HD 钱包管理的地址？</p><p>首先，可用的地址高达 <code>2^31</code> 个，这个数太大了，用户不可能用完，因此，HD 钱包只会预生成前 1000 个地址（即索引号为 0 ～ 999）并保存在本地数据库中，如果不够了，再继续扩展 1000 个，这样，HD 钱包管理的地址数量不会太大</p><p><strong>如何高效查询地址：</strong></p><p>其次，要在上千个地址集合中快速判断某个地址是否存在，查询数据库是一个非常低效的方式。以哈希表存储在内存中虽然效率很高，但管理的集合数量太多，占用的内存会非常大。</p><p>要做到高效的查询和低空间占用率，可以使用 <strong>布隆过滤器（Bloom Filter）</strong>，它是由 Burton Howard Bloom 在 1970 年提出的</p><p>其原理是将每个元素通过若干个哈希函数映射成一个位数组的若干个点，将其置 1。检索的时候，先计算给定元素对应位是否全 1，如果是全 1，则给定元素很可能存在，否则，元素必定不存在</p>`,82)])])}const C=n(t,[["render",i]]);export{E as __pageData,C as default};
